import{_ as a,o,c as i,ao as n,j as e,a as s}from"./chunks/framework.ucUddl5u.js";const m=JSON.parse('{"title":"Sessions and persistence","description":"","frontmatter":{},"headers":[],"relativePath":"concepts/sessions.md","filePath":"concepts/sessions.md","lastUpdated":null}'),r={name:"concepts/sessions.md"};function d(l,t,h,c,u,p){return o(),i("div",null,[...t[0]||(t[0]=[n('<h1 id="Sessions-and-persistence" tabindex="-1">Sessions and persistence <a class="header-anchor" href="#Sessions-and-persistence" aria-label="Permalink to &quot;Sessions and persistence {#Sessions-and-persistence}&quot;">​</a></h1><p>A <strong>session</strong> is a row in Sessions mode. The rows from every host you are connected to appear in one list, grouped by host; the machine in front of you is just another host.</p><h2 id="session-model" tabindex="-1">Hosts, sessions, REPLs <a class="header-anchor" href="#session-model" aria-label="Permalink to &quot;Hosts, sessions, REPLs {#session-model}&quot;">​</a></h2><ul><li><p>A <strong>host</strong> is a machine running the backend daemon, <code>sotd</code>.</p></li><li><p>A <strong>session</strong> is one project directory on one host. The backend calls it a <em>workspace</em>, and the words mean the same thing: one session is one row in Sessions mode and one entry in the session strip along the bottom edge. <code>Shift+Arrow</code> moves between sessions.</p></li><li><p>Each session has its own <strong>agent pane</strong> (Claude Code, Codex or a plain shell), its own <strong>Julia REPL</strong>, and its own <strong>kernel</strong>, the Julia process that serves Modules mode and file previews. The REPL and kernel start the first time something needs them, in the project&#39;s <code>Project.toml</code> environment, running the <code>julia</code> that <code>SOT_JULIA_BIN</code> names, else juliaup&#39;s default channel, else a <code>julia</code> on <code>PATH</code>.</p></li></ul>',4),e("div",{class:"sot-model",role:"img","aria-label":"One host running two sessions. Each session has its own agent pane, Julia REPL and kernel."},[e("div",{class:"sot-model-host"},[e("div",{class:"sot-model-title"},[s("host: "),e("code",null,"sotd")]),e("div",{class:"sot-model-rows"},[e("div",{class:"sot-model-row"},[e("div",{class:"sot-model-title"},[s("session "),e("code",null,"survey")]),e("span",null,"agent pane"),e("span",null,[s("Julia REPL ("),e("code",null,"Main"),s(")")]),e("span",null,"kernel")]),e("div",{class:"sot-model-row"},[e("div",{class:"sot-model-title"},[s("session "),e("code",null,"analysis")]),e("span",null,"agent pane"),e("span",null,[s("Julia REPL ("),e("code",null,"Main"),s(")")]),e("span",null,"kernel")])])])],-1),n('<p>Two sessions never share a Julia <code>Main</code>: each REPL is its own process. Inside one session, you (from the REPL drawer), the session&#39;s agent and any helper agents it starts all run code in that session&#39;s one REPL. It runs one evaluation at a time and does not queue: a request that arrives while another is running comes back as <code>busy</code> and nothing runs. The <code>julia-repl</code> skill tells agents to use separate <code>julia</code> processes for parallel runs.</p><h2 id="Capsules:-sessions-that-outlive-everything-around-them" tabindex="-1">Capsules: sessions that outlive everything around them <a class="header-anchor" href="#Capsules:-sessions-that-outlive-everything-around-them" aria-label="Permalink to &quot;Capsules: sessions that outlive everything around them {#Capsules:-sessions-that-outlive-everything-around-them}&quot;">​</a></h2><p>Each session&#39;s agent runs in a <strong>capsule</strong>: a small supervisor process (<code>sot-capsule</code>) that owns the agent&#39;s terminal and records the session to disk (its <em>voyage</em>). The frontend attaches to the capsule to draw the pane; the daemon starts capsules and lists them, but does not hold them up.</p><table tabindex="0"><thead><tr><th style="text-align:right;">What goes away</th><th style="text-align:right;">What happens to the session</th></tr></thead><tbody><tr><td style="text-align:right;">the network, or the laptop lid</td><td style="text-align:right;">nothing — the frontend reconnects on its own when the network is back; <code>F5</code> retries at once</td></tr><tr><td style="text-align:right;">the frontend (quit, crash, relaunch)</td><td style="text-align:right;">nothing — the next frontend reattaches</td></tr><tr><td style="text-align:right;">the daemon (restart, upgrade)</td><td style="text-align:right;">the capsule keeps running and the restarted daemon re-adopts it</td></tr></tbody></table><p>On Linux each capsule supervisor runs in its own transient <code>systemd --user</code> scope, outside the daemon&#39;s unit, which is what lets it survive a daemon restart. On a host with no reachable user systemd manager it runs in a degraded mode that shares the daemon&#39;s lifetime, and the daemon log says why.</p><h2 id="Where-the-state-lives" tabindex="-1">Where the state lives <a class="header-anchor" href="#Where-the-state-lives" aria-label="Permalink to &quot;Where the state lives {#Where-the-state-lives}&quot;">​</a></h2><p>The daemon&#39;s state root is <code>${XDG_STATE_HOME:-~/.local/state}/sot</code>: the capsule records and the daemon&#39;s own <code>sotd.log</code>. It must be a <strong>local, durable filesystem</strong> — the daemon refuses to start a capsule on a network or volatile filesystem rather than risk the record. On a home directory shared across servers, give each host its own local state root (see <a href="/ship-of-tools/dev/guide/troubleshooting#A-session-will-not-start-on-a-shared-home">Troubleshooting</a>).</p><h2 id="Switching-and-restarts" tabindex="-1">Switching and restarts <a class="header-anchor" href="#Switching-and-restarts" aria-label="Permalink to &quot;Switching and restarts {#Switching-and-restarts}&quot;">​</a></h2><p>Switching the active session is a frontend state change: it never restarts a REPL or kernel, so each session&#39;s Julia state is where you left it, and two sessions can run different versions of the same package side by side.</p><p>The kernels and REPLs are children of the daemon, so a daemon restart restarts them. The agents survive it; Julia state does not.</p><h2 id="Reconnecting" tabindex="-1">Reconnecting <a class="header-anchor" href="#Reconnecting" aria-label="Permalink to &quot;Reconnecting {#Reconnecting}&quot;">​</a></h2><p>Every connect sends the client&#39;s session id and the last revision it saw; the daemon replays the missed events from a bounded ring, or sends a fresh snapshot if the client is too far behind. That is why a reconnect puts you back exactly where you were. Protocol details are in <a href="./../design/backend">Design: backend and sessions</a>.</p>',12)])])}const v=a(r,[["render",d]]);export{m as __pageData,v as default};
